/**
 * @name Command injection via os.system or subprocess
 * @description Using os.system or subprocess with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graphs to find command execution sinks
    exists(API::CallNode call |
      // os.system calls
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.call, subprocess.run, subprocess.Popen
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // subprocess.check_call, subprocess.check_output
      call = API::moduleImport("subprocess").getMember(["check_call", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description Using untrusted input in file paths can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Comprehensive security vulnerability check
 * @description Check for multiple common security vulnerabilities
 * @kind problem
 * @problem.severity warning
 * @id py/comprehensive-check
 * @tags security
 */

import python
import semmle.python.ApiGraphs

from DataFlow::CallCfgNode call
where
  // Check for eval/exec usage
  call = API::moduleImport("builtins").getMember(["eval", "exec", "compile"]).getACall() or
  // Check for pickle usage
  call = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall() or
  call = API::moduleImport("cPickle").getMember(["load", "loads", "Unpickler"]).getACall() or
  // Check for yaml unsafe load
  call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() or
  // Check for marshal usage
  call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() or
  // Check for shelve usage
  call = API::moduleImport("shelve").getMember("open").getACall() or
  // Check for os.system
  call = API::moduleImport("os").getMember("system").getACall() or
  // Check for subprocess calls
  call = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() or
  // Check for tempfile.mktemp (insecure)
  call = API::moduleImport("tempfile").getMember("mktemp").getACall() or
  // Check for random module (cryptographically insecure)
  call = API::moduleImport("random").getMember(["random", "randint", "choice", "shuffle"]).getACall()
select call, "Potential security vulnerability: " + call.toString()
